    constructor(C _c) { c = _c; }
    function run(address nonOwner, uint256 initialBet, uint256 newBet) public payable {
        require(nonOwner != address(0x0));
        require(initialBet > 0 && newBet != initialBet);
        // set initial betLimit as owner (deployer is owner)
        c.AdjustBetAmounts(initialBet);
        uint256 betBefore = c.currentBetLimit();
        // nonOwner attempts to change betLimit
        bool reverted; try c.AdjustBetAmounts(newBet) { reverted = false; } catch { reverted = true; }
        uint256 betAfter = c.currentBetLimit();
        assert(reverted || betAfter == betBefore);
    }
}

